28: /// Return the number of items that can be written before crossing the current blob boundary.
29: ///
30: /// `position` is the next logical item position and `remaining` is the number of items left in the
31: /// append batch. The result is always at least one when `remaining > 0`.
32: fn batch_count_to_blob_boundary(position: u64, remaining: usize, items_per_blob: u64) -> usize {
33:     let pos_in_blob = position % items_per_blob;
34:     let remaining_space = items_per_blob - pos_in_blob;
35: 
36:     // Keep the min in u64 so a 2^32-item blob space does not truncate to zero on 32-bit targets.
37:     remaining_space.min(remaining as u64) as usize
38: }
