40: /// Return the blob containing `position`.
41: ///
42: /// # Examples
43: ///
44: /// ```ignore
45: /// // With 10 items per blob:
46: /// assert_eq!(position_to_blob(0, 10), 0);   // position 0 -> blob 0
47: /// assert_eq!(position_to_blob(9, 10), 0);   // position 9 -> blob 0
48: /// assert_eq!(position_to_blob(10, 10), 1);  // position 10 -> blob 1
49: /// assert_eq!(position_to_blob(25, 10), 2);  // position 25 -> blob 2
50: /// assert_eq!(position_to_blob(30, 10), 3);  // position 30 -> blob 3
51: /// ```
52: const fn position_to_blob(position: u64, items_per_blob: u64) -> u64 {
53:     position / items_per_blob
54: }
