56: /// Return the first position stored in `blob`.
57: fn blob_first_position(blob: u64, items_per_blob: u64) -> Result<u64, Error> {
58:     blob.checked_mul(items_per_blob)
59:         .ok_or(Error::OffsetOverflow)
60: }
61: 
62: /// Return the exclusive logical end for `blob`, clamped to `end`.
63: const fn blob_end_position(blob: u64, items_per_blob: u64, end: u64) -> u64 {
64:     // No positions exist, so `end - 1` would underflow
65:     if end == 0 {
66:         return 0;
67:     }
68: 
69:     // This blob contains `end - 1`, so clamp to the journal end
70:     let end_blob = (end - 1) / items_per_blob;
71:     if blob >= end_blob {
72:         return end;
73:     }
74: 
75:     // Earlier blobs have a representable natural boundary
76:     (blob + 1) * items_per_blob
77: }
