79: /// A decoded batch yielded by [ReplayBatchState::next_batch] paired with the advanced state, or
80: /// `None` once the state is exhausted.
81: type ReplayBatch<S> = Option<(Vec<Result<(u64, <S as ReplayBatchState>::Item), Error>>, S)>;
82: 
83: /// Per-blob replay state that yields decoded item batches.
84: trait ReplayBatchState: Sized {
85:     /// The decoded item type.
86:     type Item;
87: 
88:     /// Decode the next batch from this blob state.
89:     fn next_batch(self) -> impl Future<Output = ReplayBatch<Self>> + Send;
90: }
91: 
92: /// Stream driver over per-blob replay states.
93: struct ReplayStreamState<S: ReplayBatchState> {
94:     /// Remaining blob states, in ascending blob order.
95:     states: std::vec::IntoIter<S>,
96:     /// State currently being drained.
97:     current: Option<S>,
98:     /// Set after the first error so the stream terminates cleanly.
99:     done: bool,
100: }
101: 
102: impl<S: ReplayBatchState + Send> ReplayStreamState<S>
103: where
104:     S::Item: Send,
105: {
106:     /// Yield the next decoded batch.
107:     async fn next(mut self) -> Option<(Vec<Result<(u64, S::Item), Error>>, Self)> {
108:         loop {
109:             if self.done {
110:                 return None;
111:             }
112: 
113:             let state = match self.current.take().or_else(|| self.states.next()) {
114:                 Some(state) => state,
115:                 None => return None,
116:             };
117: 
118:             match state.next_batch().await {
119:                 Some((batch, state)) => {
120:                     if batch.iter().any(Result::is_err) {
121:                         self.done = true;
122:                         self.current = None;
123:                     } else {
124:                         self.current = Some(state);
125:                     }
126:                     return Some((batch, self));
127:                 }
128:                 None => {
129:                     self.current = None;
130:                 }
131:             }
132:         }
133:     }
134: }
