136: /// Build a stream from per-blob replay states.
137: fn replay_stream_from_states<S>(
138:     states: Vec<S>,
139: ) -> impl Stream<Item = Result<(u64, S::Item), Error>> + Send
140: where
141:     S: ReplayBatchState + Send,
142:     S::Item: Send,
143: {
144:     stream::unfold(
145:         ReplayStreamState {
146:             states: states.into_iter(),
147:             current: None,
148:             done: false,
149:         },
150:         ReplayStreamState::next,
151:     )
152:     .flat_map(stream::iter)
153: }
