155: /// A read-only, position-based view of a contiguous journal.
156: ///
157: /// Maintains a monotonically increasing position counter where each appended item receives a unique
158: /// position starting from 0.
159: pub trait Contiguous: Send + Sync {
160:     /// The type of items stored in the journal.
161:     type Item: Send;
162: 
163:     /// Returns [start, end) with a guaranteed stable pruning boundary.
164:     fn bounds(&self) -> Range<u64>;
165: 
166:     /// Read the item at the given position.
167:     ///
168:     /// Guaranteed not to return [Error::ItemPruned] for positions within `bounds()`.
169:     fn read(&self, position: u64) -> impl Future<Output = Result<Self::Item, Error>> + Send + Sync;
170: 
171:     /// Read multiple items at the given positions, which must be strictly increasing.
172:     ///
173:     /// Equivalent to serving every position [`try_read_many_sync`](Self::try_read_many_sync)
174:     /// declines with one batched read. Implementations may fuse the two passes.
175:     fn read_many(
176:         &self,
177:         positions: &[u64],
178:     ) -> impl Future<Output = Result<Vec<Self::Item>, Error>> + Send;
179: 
180:     /// Read an item if it can be done synchronously (e.g. without I/O), returning `None`
181:     /// otherwise. Decode failures surface as `None` and the async read path reports the error.
182:     fn try_read_sync(&self, position: u64) -> Option<Self::Item>;
183: 
184:     /// Probe multiple strictly increasing positions, serving those that can be read
185:     /// synchronously (e.g. from a page cache) and returning one slot per position. Positions
186:     /// that require I/O, fail to decode, or fall outside `bounds()` decline to `None`. The
187:     /// async read paths are the sole error authority for declined positions.
188:     fn try_read_many_sync(&self, positions: &[u64]) -> Vec<Option<Self::Item>>;
189: 
190:     /// Return a stream of all items starting from `start_pos`, bounded by `bounds()`.
191:     ///
192:     /// `buffer` controls the replay byte budget for each chunk. Every backing blob read from
193:     /// sealed history uses `read_options`. Backing reads from the live writable tip instead use
194:     /// [ReadOptions::DONT_CACHE] on page-cache misses because the cache retains the fetched pages.
195:     fn replay(
196:         &self,
197:         start_pos: u64,
198:         buffer: NonZeroUsize,
199:         read_options: ReadOptions,
200:     ) -> impl Future<
201:         Output = Result<impl Stream<Item = Result<(u64, Self::Item), Error>> + Send, Error>,
202:     > + Send;
203: }
